"""Restore OpenBank's task snapshot and verify its visible starting point.

The macOS author queue reuses one VM across tasks.  A previous OpenBank task
can therefore leave Jordan signed in and bill/transfer records in the app.
The local app's ``/api/dev/reset`` endpoint restores its documented seed; this
initializer uses it before each task, removes only that task's expected output
file from the guest Desktop, then verifies the fresh state and login screen.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: Port OpenBank serves on inside the guest.
DEFAULT_PORT = 4340


class OpenBankSnapshotInitializer(MacAppInitializer):
    """Reset OpenBank to its seed for each episode on a shared VM."""

    INITIALIZER_ID = "initializers.macos.openbank:OpenBankSnapshotInitializer"
    APP_NAME = "OpenBank"
    BUNDLE_ID = "local.osomni.openbank"
    SETTLE_MS = 2500

    def __init__(self) -> None:
        self._did_snapshot_reset = False

    def _result(self, status, message, metadata):
        result = super()._result(status, message, metadata)
        if self._did_snapshot_reset:
            result.metadata["read_only"] = False
            result.metadata["inter_task_snapshot_reset"] = True
        return result

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        port, state, notes = self._read_loopback(
            controller,
            [params.get("port") or DEFAULT_PORT],
            ["/api/evaluation"],
            what="OpenBank state",
        )
        if port is None:
            raise InitializationError(
                "OpenBank did not answer GET /api/evaluation"
                + (f" ({'; '.join(notes)})" if notes else "")
            )
        document = self._endpoint_body(state, "/api/evaluation")
        self._check_expected_customer(document, params)

        # Restore the task's baseline every time: tasks intentionally run on a
        # single persistent VM, but each OpenBank task specifies the same seed.
        self._reset_task_snapshot(controller, port, params)
        self._did_snapshot_reset = True
        port, state, notes = self._read_loopback(
            controller,
            [params.get("port") or DEFAULT_PORT],
            ["/api/evaluation"],
            what="OpenBank state after task snapshot reset",
        )
        if port is None:
            raise InitializationError(
                "OpenBank did not recover after restoring its task snapshot"
                + (f" ({'; '.join(notes)})" if notes else "")
            )
        document = self._endpoint_body(state, "/api/evaluation")
        session = dict(document.get("session") or {})
        if session.get("loggedIn"):
            raise InitializationError("OpenBank remained signed in after restoring its task snapshot")
        self._check_expected_customer(document, params)

        self._check_indexed(document, "accounts", params.get("required_accounts"), "account")
        self._check_indexed(document, "billers", params.get("required_billers"), "biller")
        self._check_indexed(document, "recipients", params.get("required_recipients"), "recipient")
        self._check_indexed(
            document, "transactions", params.get("required_transactions"), "transaction"
        )
        self._check_absent_recipients(document, params.get("required_absent_recipient_names"))
        self._check_count(document, "recipients", params.get("expected_recipient_count"))
        self._check_empty(document, "billPayments")
        self._check_empty(document, "transfers")
        self._check_absent_file(controller, params.get("required_absent_file"))

        self._wait_for_visible(
            controller,
            [params.get("expected_login_label") or "Sign In"],
            timeout=float(params.get("visible_timeout_seconds") or 45.0),
            poll_seconds=float(params.get("poll_interval_seconds") or 1.0),
            what="the OpenBank login page",
        )

        return (
            f"OpenBank answers on port {port} with the signed-out "
            f"{dict(document.get('customer') or {}).get('displayName')} seed, "
            f"{len(document.get('accounts') or [])} accounts, "
            f"{len(document.get('recipients') or [])} recipients and no target records, "
            "after restoring the per-task app snapshot"
        )

    @staticmethod
    def _check_expected_customer(document: Mapping[str, Any], params: Mapping[str, Any]) -> None:
        customer = dict(document.get("customer") or {})
        expected_id = str(params.get("expected_customer_id") or "cust-jordan").strip()
        expected_email = str(params.get("expected_customer_email") or "jordan@openbank.local").strip().casefold()
        if str(customer.get("id") or "").strip() != expected_id:
            raise InitializationError("OpenBank does not carry the expected Jordan Lee seed")
        if str(customer.get("email") or "").strip().casefold() != expected_email:
            raise InitializationError("OpenBank carries an unexpected seeded customer")
        session = dict(document.get("session") or {})
        if session.get("loggedIn"):
            user = dict(session.get("user") or {})
            active_id = str(user.get("id") or session.get("id") or "").strip()
            active_email = str(user.get("email") or session.get("email") or "").strip().casefold()
            if active_id != expected_id or active_email != expected_email:
                raise InitializationError(
                    "OpenBank is signed in as an unexpected account; refusing to reset it"
                )

    def _reset_task_snapshot(
        self, controller: Any, port: int, params: Mapping[str, Any]
    ) -> None:
        """Reset app business state and only the task's expected Desktop output."""
        output_path = str(params.get("required_absent_file") or "").strip()
        if output_path:
            allowed_prefixes = ("~/Desktop/", "/Users/bench/Desktop/")
            if not output_path.startswith(allowed_prefixes):
                raise InitializationError("OpenBank task output must be a file on the guest Desktop")
            if Path(output_path).name in ("", ".", ".."):
                raise InitializationError("OpenBank task output path is invalid")
        reset_payload = json.dumps({"mode": params.get("evaluation_mode")})
        script = "\n".join(
            [
                "import json, urllib.request",
                f"url = 'http://127.0.0.1:{int(port)}/api/dev/reset'",
                f"data = {reset_payload!r}.encode('utf-8')",
                "request = urllib.request.Request(url, data=data, headers={'Content-Type': 'application/json'}, method='POST')",
                "with urllib.request.urlopen(request, timeout=10) as response:",
                "    body = json.loads(response.read().decode('utf-8'))",
                "session = dict(body.get('session') or {})",
                "if body.get('ok') is not True or session.get('loggedIn'):",
                "    raise RuntimeError('OpenBank dev reset did not restore a signed-out state')",
                "removed_output = False",
                "if " + repr(output_path) + ":",
                "    from pathlib import Path",
                "    target = Path(" + repr(output_path) + ").expanduser()",
                "    desktop = Path.home() / 'Desktop'",
                "    if target.parent.resolve() != desktop.resolve() or target.name in ('', '.', '..'):",
                "        raise RuntimeError('refusing to remove output outside the guest Desktop')",
                "    if target.exists() or target.is_symlink():",
                "        target.unlink()",
                "        removed_output = True",
                "print(json.dumps({'ok': True, 'logged_in': False, 'removed_output': removed_output}))",
            ]
        )
        result = self._guest_python(controller, script, timeout=20)
        output = str(result.get("stdout") or result.get("output") or "")
        error = str(result.get("stderr") or result.get("error") or "")
        if int(result.get("returncode", -1)) != 0:
            raise InitializationError(
                "OpenBank task snapshot reset failed: "
                + (error.strip() or output.strip() or f"exit {result.get('returncode')}")
            )
        try:
            reset_state = json.loads([line for line in output.splitlines() if line.strip()][-1])
        except (IndexError, ValueError) as exc:
            raise InitializationError("OpenBank task snapshot reset returned no verifiable result") from exc
        if reset_state.get("ok") is not True or reset_state.get("logged_in") is not False:
            raise InitializationError("OpenBank task snapshot reset was not confirmed")

        app_name = str(params.get("app_name") or self.APP_NAME).strip()
        app_path, _ = self._inspect_installation(controller, app_name)
        executable = str(Path(app_path) / "Contents" / "MacOS" / "OpenAppShell")
        stop_script = "\n".join(
            [
                "import json, os, signal, subprocess, time",
                "expected = " + repr(executable),
                "lines = subprocess.check_output(['/bin/ps', '-axo', 'pid=,comm='], text=True).splitlines()",
                "pids = []",
                "for line in lines:",
                "    fields = line.strip().split(None, 1)",
                "    if len(fields) == 2 and fields[1] == expected and fields[0].isdigit(): pids.append(int(fields[0]))",
                "for pid in pids:",
                "    try: os.kill(pid, signal.SIGTERM)",
                "    except ProcessLookupError: pass",
                "deadline = time.monotonic() + 8",
                "while time.monotonic() < deadline:",
                "    active = []",
                "    for pid in pids:",
                "        try: os.kill(pid, 0); active.append(pid)",
                "        except ProcessLookupError: pass",
                "    if not active: break",
                "    time.sleep(0.2)",
                "print(json.dumps({'stopped': not bool(active), 'pid_count': len(pids)}))",
            ]
        )
        stopped = self._guest_python(controller, stop_script, timeout=15)
        stop_output = str(stopped.get("stdout") or stopped.get("output") or "")
        stop_error = str(stopped.get("stderr") or stopped.get("error") or "")
        if int(stopped.get("returncode", -1)) != 0:
            raise InitializationError(
                "OpenBank could not reload after restoring its task snapshot: "
                + (stop_error.strip() or stop_output.strip() or f"exit {stopped.get('returncode')}")
            )
        try:
            stop_state = json.loads([line for line in stop_output.splitlines() if line.strip()][-1])
        except (IndexError, ValueError) as exc:
            raise InitializationError("OpenBank app shutdown returned no verifiable result") from exc
        if not stop_state.get("stopped"):
            raise InitializationError("OpenBank app did not stop cleanly before reloading")
        launch = controller.launch_app(app_name)
        if isinstance(launch, Mapping) and launch.get("success") is False:
            raise InitializationError(
                f"OpenBank could not relaunch after resetting: {launch.get('error') or launch.get('message')}"
            )
        self._wait_for_process(controller, app_path)
        self._settle(params)

    # ------------------------------------------------------------ checks
    @staticmethod
    def _by_id(records: Any) -> dict[str, Any]:
        found: dict[str, Any] = {}
        for record in records or []:
            if isinstance(record, Mapping) and record.get("id"):
                found[str(record["id"])] = dict(record)
        return found

    def _check_indexed(
        self, document: Mapping[str, Any], collection: str, required: Any, label: str
    ) -> None:
        if not required:
            return
        present = self._by_id(document.get(collection))
        for identifier, expected in dict(required).items():
            record = present.get(str(identifier))
            if record is None:
                raise InitializationError(f"OpenBank is missing the seeded {label} {identifier}")
            for field, value in dict(expected or {}).items():
                if record.get(field) != value:
                    raise InitializationError(
                        f"OpenBank {label} {identifier} has {field}={record.get(field)!r}, "
                        f"expected {value!r}"
                    )

    def _check_absent_recipients(self, document: Mapping[str, Any], names: Any) -> None:
        wanted = {str(name) for name in (names or [])}
        if not wanted:
            return
        present = {str((record or {}).get("name")) for record in document.get("recipients") or []}
        unexpected = sorted(wanted & present)
        if unexpected:
            raise InitializationError(
                f"OpenBank already carries the target recipient(s) {', '.join(unexpected)}"
            )

    @staticmethod
    def _check_count(document: Mapping[str, Any], collection: str, expected: Any) -> None:
        if expected is None:
            return
        observed = len(document.get(collection) or [])
        if observed != int(expected):
            raise InitializationError(
                f"OpenBank carries {observed} {collection}, expected {int(expected)}"
            )

    @staticmethod
    def _check_empty(document: Mapping[str, Any], collection: str) -> None:
        records = document.get(collection) or []
        if records:
            raise InitializationError(
                f"OpenBank already carries {len(records)} {collection} before the task ran"
            )

    def _check_absent_file(self, controller: Any, path: Any) -> None:
        if not path:
            return
        script = "\n".join(
            [
                "import json",
                "from pathlib import Path",
                f"target = Path({str(path)!r}).expanduser()",
                "print(json.dumps({'path': str(target), 'exists': target.exists()}))",
            ]
        )
        observed = self._guest_json(controller, script, what="the task document")
        if observed.get("exists"):
            raise InitializationError(
                f"{observed.get('path')} already exists before the task ran"
            )
